// Package content holds the files compiled into mw: the default protocol checklist, the role
// prompts, the coordinated job kit, the fanfare icon and default sound, and the built-in fanfare
// catalogue (fanfare_sources.go, generated by scripts/gen_fanfare_sources.py).
package content

import "embed"

// Protocol is PROTOCOL.md, the default wave checklist.
//
//go:embed PROTOCOL.md
var Protocol string

// Prompts holds prompts/*.md, the role prompt templates.
//
//go:embed prompts/*.md
var Prompts embed.FS

// Kit holds kit/*, the coordinated job kit files.
//
//go:embed kit/*
var Kit embed.FS

// FanfareIcon is the notification icon.
//
//go:embed assets/fanfare-icon.png
var FanfareIcon []byte

// FanfareWAV is the synthesized default fanfare (scripts/gen_fanfare_default.py).
//
//go:embed assets/fanfare-default.wav
var FanfareWAV []byte

// FanfareTrack is one downloadable recording of a built-in fanfare pair.
type FanfareTrack struct {
	Kind, Ext, URL, Source, License, Attribution, Title string
	SHA256                                              string // optional pin; a download that differs fails
}

// FanfarePair is a built-in fanfare/finale set.
type FanfarePair struct {
	Name, Label string
	Tracks      []FanfareTrack
}
